use super::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── N: the masked-in-place field law — the weight field never
        // leaves its word; the OTHER operand carries the 2^-offset
        // prescale through the f32 exponent field. ─
        KernelRule {
            rule_id: "masked-in-place-field-prescale-other-operand".to_string(),
            gpu_concept: "MECHANISM (sub-word quant-field consumption without a shift-down; category N — dtype/bit-pattern specialization): consume a packed sub-word field of an integer weight word AS A FLOAT WITHOUT SHIFTING IT OUT OF THE WORD — mask it IN PLACE (the field's bits stay where they are) and pre-scale the OTHER operand of the product by 2^-offset through an f32 exponent-field bit pattern, so the field's implicit 2^offset factor and the prescale cancel and every product is exact. THE LAW, verbatim in-source (simd_qmm.zig:28-30): '// Value 8j + p of a 64-group's words (j = k-slot, p = pass): 4 and 8 bits masked in place, the input pre-scaled by wpre(p) to cancel the shift; 6 bits straddle words, so they are shifted down and wpre is 1.' THE PRESCALE, verbatim (simd_qmm.zig:31-33): 'template <int BITS> inline float wpre(int p) { return BITS == 6 ? 1.0f : as_type<float>(uint(127 - (BITS == 4 ? 4 * p : 8 * (p % 4))) << 23); }' — a power of two BUILT BY WRITING THE EXPONENT FIELD directly (127 - shift in bits 23-30, mantissa zero): no table, no conversion op, 2^-shift exact by construction. THE IN-PLACE MASK, verbatim (simd_qmm.zig:38): 'return float(w0 & (((1u << BITS) - 1u) << off));' — the masked integer IS field << off (the field stays at its bit offset), so the float is field * 2^off EXACTLY (small integers are exact in fp32), and the pair (x * 2^-off) * (field * 2^off) = x * field with each factor exact and the exponents cancelling — NO per-element variable shift, NO int-to-float conversion ladder inside the dot. THE CONSUMPTION PAIR, verbatim: the staging multiplies once per staged element — 'xs[gl * XP + 8 * s + i] = bf8(v, s) * wpre<BITS>(s);' (simd_qmm.zig:80, into threadgroup memory) — and the FMA loop reads the masked weight — 'for (int i = 0; i < 8; i++) P[u] = fma(xq[i], wfield<BITS>(wd[u], i, s), P[u]);' (simd_qmm.zig:110); the tensor-unit path is the same pair through simdgroup MMA — 'const float ps = wpre<BITS>(s);' feeds the x-side fragment bm while 'am.thread_elements()[0] = wfield<BITS>(wv[t], 0, s);' rides the other operand (simd_qmm.zig:272,282-283), and the PREP kernel stages 'the `mma` fragments of x pre-scaled by wpre (XF[tile][g][s][lane]; rows past R copy row R - 1)' (simd_qmm.zig:362-364) — THE PRESCALE IS PAID AT STAGING, once per staged activation element, amortized over every weight row that reads it; the shift it replaces would be paid per (row, group, pass) inside the hot FMA loop. THE OFFSET MUST BE A FUNCTION OF THE PASS ALONE — that is the law's boundary: 4-bit fields pack 8 per 32-bit word (off = 4*p) and 8-bit pack 4 (off = 8*(p%4)), so one wpre(p) serves every k-slot; 6-bit fields pack 5.33 per word (48 bits per 8 fields) — the offset depends on the k-slot j too AND fields straddle word boundaries, so the in-place mask cannot serve and THE EXCEPTION IS PART OF THE LAW, verbatim (simd_qmm.zig:37): 'if (BITS == 6) return float((off <= 26 ? w0 >> off : (w0 >> off) | (lw[bit / 32 + 1] << (32 - off))) & 63u);' — the conventional shift-down (with the two-word straddle spelled explicitly) and wpre = 1. THE ALU TWIN (qmv_nax2.zig, the second kernel carrying the same law in plain multiplies — no bit-pattern needed when the scale is an ordinary float): the group scale is pre-multiplied per pass, verbatim (qmv_nax2.zig:153-158): 'const float sv = float(scales[wrow[j] * K_g + g]);' then 's0[j] = sv;' 's1[j] = sv * 0.25f;' 's2[j] = sv * 0.0625f;' 's3[j] = sv * 0.015625f;' (2^0, 2^-2, 2^-4, 2^-6), and the 2-bit codes are consumed MASKED AT THEIR BYTE OFFSETS, verbatim (qmv_nax2.zig:180-183): 'v0 = s0[j] * float(by & 0x03u) + bz[j];' 'v1 = s1[j] * float(by & 0x0cu) + bz[j];' 'v2 = s2[j] * float(by & 0x30u) + bz[j];' 'v3 = s3[j] * float(by & 0xc0u) + bz[j];' — the field at bits 2-3 reads as field*4, cancelled by sv*0.25; NO shift anywhere. DECISION CONTENT: (a) never shift the weight field down when the other operand can absorb the offset — the shift is per-element per-row in the hot loop, the prescale is once per staged element amortized over N weight rows; (b) build the power-of-two by writing the exponent field (uint(127 - shift) << 23) — zero ALU beyond the reinterpret; (c) the pair is legal exactly where the field's bit offset is a function of the pass index alone (bit widths dividing the 32-bit word: 4, 8); widths that do not divide (6) take the shift-down with wpre = 1 — the exception is encoded in the SAME two functions, not a separate path; (d) when the correction target is a plain float scale, multiply the scale by 2^-2k per pass instead of touching the bit pattern (the ALU twin). REGIME: group-quantized weight decode feeding an FMA/MMA dot — every weight field at a non-zero bit offset inside its word; the activation side staged once and read by many weight rows (the prescale amortizes); NOVEL numerics (the product pair is exact by construction — each factor exact, exponents cancel) and PORTABLE host/ALU logic: pure integer masks + fp32 bit patterns, CPU-exact. ANTI-REGIME: bit widths that do not divide the word (the 6-bit straddle — wpre = 1 there); consumers needing the field's INTEGER value rather than a product (no other operand to carry the prescale); single-use operands (the prescale does not amortize — one multiply either way). KINSHIP (do not double-count): lop3-int4-to-half2-dequant (entries_gpu_09) owns the magic-exponent EMBEDDING decode — '(a & b) | c' plants the f16 exponent into the weight word in the SAME instruction that extracts the nibble (bits | 0x6400); THIS never reinterprets the weight word as float — the field stays an integer at its offset and the OTHER operand carries the power-of-two; prmt-int8-to-half2-dequant (same file) is the byte-lane embedding twin; minifloat-normal-code-shift-bias-diff-decode (entries_gpu_77) owns the exponent-field decode family and its PLACED arm (E2M1_F16_LIFT) is the nearest kin — decode a value 2^14 short of itself and fold the lift into the caller's factor ONCE — but its offset is a CONSTANT folded into a per-block scale, while THIS cancels a PER-PASS bit offset by multiplying the other operand of the dot; the qmv_nax2 HDQ arm ('(u & 0x00030003u) | 0x64006400u', qmv_nax2.zig:174) is the EMBEDDING face inside this very source file — the two faces are one family: embed the exponent in the weight word, or pre-scale the activation; pick by whether the weight field can stay an integer. Benchable via a Rust-idiom fixture (the x86-GOAT precedent B231/116 — portable CPU-exact exponent-field + integer-mask logic; a fixture comparing shift-down decode vs masked-in-place + prescale over random packed words pins both exactness and op-count). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (simd_qmm.zig:28-39 the law comment + wpre + wfield, :80/:110 the scalar staging + FMA consumption, :272,:282-283 the mma consumption pair, :362-364 the PREP staging doc; qmv_nax2.zig:153-158,:180-183 the ALU twin; every quote verbatim at the pin this session; repo MIT — simd_qmm ported from TensorFold's simd_qmm.py per its header). Batch 242 / Plan 244 / Research 274. GOAT BENCH LANDED (bench_008 / Bench 117, plan 246 — the Benchable-via clause above discharged): G1 988 cases BIT-IDENTICAL across all four arms (4-bit + 8-bit + the 2-bit ALU twin + the 6-bit straddle exception; edge words + the ±2^-98 regime boundary where x·2^-28 = 2^-126 the smallest normal — the LAST exact prescale; below |x·2^-off| < 2^-126 the prescale can round (subnormal) and bit-identity is NOT claimed, the disclosed anti-regime); G2 measured SPLIT at 25 shapes × 3 faces (interleaved best-of-5, correctness-coupled sinks, provenance-gated): the byte-aligned faces WIN — the 2-bit ALU twin 1.28-1.34× (the ladder also folds the per-element (x·sv) multiply into staging) and 8-bit 1.07-1.10× (the naive shift-down pays scalar-gather loads + lane-repacking shuffles while the byte-aligned mask is a shuffle-free pand) — and the 4-bit half-lane face is a measured CPU ANTI-CASE 0.87-0.94× (the naive psrld-imm + punpckldq + cvtdq2ps lowering beats the masked form's broadcast + exponent-trick convert chain — the u32-to-f32 of exponent-region values (up to 2^31 at off=28) costs por 0x53000000/subps/addps; the law's native regime is the GPU where per-lane shifts are expensive; re-armed on a host/toolchain move); G4 zero-alloc both arms all faces; the OP-COUNT LEDGER at rows=512 k=4096: 2,097,152 hot-loop shifts eliminated for 4,096 staged multiplies (512:1 — the amortization axis, structural). LANE INTEL: LLVM's own lowering of the masked convert builds the float from the exponent field via por/subps bit patterns — the backend independently discovered this rule's technique. The fixture exits 1 under the strict all-faces wall-clock bar (the honest split record); the rule's claimed axes (exactness + op-count) PASS.".to_string(),
            ref_shape: "// naive: every weight field is shifted DOWN to unit position and\n// converted per element — a variable shift + a mask + an int->float\n// conversion inside the dot loop, for every weight row, every group,\n// every pass.\nfn dot_group_naive(x: &[f32; 8], w_words: &[u32; 8], bits: u32) -> f32 {\n    let mut acc = 0.0f32;\n    for p in 0..8usize {\n        let bit = p * bits as usize; // field p's bit offset in the group\n        let word = w_words[bit / 32];\n        let off = bit % 32;\n        // shift the field down (two ops), then convert — per element,\n        // per row, per group\n        let field = ((word >> off) & ((1u32 << bits) - 1)) as f32;\n        acc += x[p] * field;\n    }\n    acc\n}".to_string(),
            opt_pattern: "// optimized: the field is masked IN PLACE (it stays at its bit\n// offset, so the masked integer IS field << off and converts exactly\n// to field * 2^off), and the OTHER operand was pre-scaled by 2^-off\n// via the f32 exponent field at STAGING time — the product is exact,\n// no per-element shift, no conversion ladder. The 6-bit straddle\n// exception shifts down conventionally with wpre = 1.\nfn wpre(bits: u32, p: usize) -> f32 {\n    if bits == 6 {\n        1.0 // 6-bit fields straddle words: shifted down, no prescale\n    } else {\n        let shift = if bits == 4 { 4 * p } else { 8 * (p % 4) };\n        // 2^-shift written straight into the exponent field — no\n        // table, no conversion op, exact by construction\n        f32::from_bits((127u32 - shift as u32) << 23)\n    }\n}\n\nfn wfield_inplace(w0: u32, bits: u32, off: usize) -> f32 {\n    // mask in place: field stays at its offset -> float == field * 2^off\n    let mask = ((1u32 << bits) - 1) << off;\n    (w0 & mask) as f32\n}\n\nfn dot_group_masked(xs_pre: &[f32; 8], w_words: &[u32; 8], bits: u32) -> f32 {\n    let mut acc = 0.0f32;\n    for p in 0..8usize {\n        let bit = p * bits as usize;\n        let off = bit % 32;\n        let w0 = w_words[bit / 32];\n        // xs_pre[p] was staged as x[p] * wpre(bits, p) — ONE multiply\n        // at staging, amortized over every weight row that reads it\n        acc += xs_pre[p] * wfield_inplace(w0, bits, off);\n    }\n    acc\n}\n\n// the ALU twin (plain-float form): pre-multiply the group scale per\n// pass and consume the 2-bit codes masked at their byte offsets.\nfn scale_prescale(sv: f32) -> [f32; 4] {\n    [sv, sv * 0.25, sv * 0.0625, sv * 0.015625] // 2^0, 2^-2, 2^-4, 2^-6\n}\n\nfn decode_byte(by: u8, s: &[f32; 4], bz: f32) -> [f32; 4] {\n    [\n        s[0] * (by & 0x03) as f32 + bz, // field at bits 0-1, in place\n        s[1] * (by & 0x0c) as f32 + bz, // bits 2-3: reads field*4,\n        s[2] * (by & 0x30) as f32 + bz, // cancelled by sv * 0.25\n        s[3] * (by & 0xc0) as f32 + bz, // bits 6-7: cancelled by 2^-6\n    ]\n}".to_string(),
        },
        // ── D: the clone-the-upstream-predicate law — the admission
        // boundary is the framework's own kernel-family boundary,
        // because below it the sibling sums in another order. ─
        KernelRule {
            rule_id: "admission-clones-upstream-dispatch-for-bit-order".to_string(),
            gpu_concept: "MECHANISM (fast-kernel admission vs the upstream framework's own dispatch boundary; category D — dispatch admission): when a replacement kernel serves a call the UPSTREAM framework routes to one of SEVERAL kernels, the replacement's admission predicate must CLONE the upstream's own dispatch predicate — verbatim, not approximated, not widened — because below the predicate's bound the framework routes to a DIFFERENT kernel whose floating-point summation order differs, and bit-exact consumers (MTP verify rounds comparing a drafted window against one-row steps) break. THE LAW, verbatim in-source (gather_qmm_nax.zig:59-62): '// Take only the calls MLX sends to its sorted row-block kernel (`B >= 16 && B / E >= 4`, quantized.cpp GatherQMM::eval_gpu); below that it runs gather_qmv, which sums in another order, and MTP verify rounds must keep its bits.' THE PREDICATE, verbatim (gather_qmm_nax.zig:63): 'if (ids[0] < 16 or @divTrunc(ids[0], ws[0]) < 4) return false;' — a transcription of the upstream's own C++ predicate (batch B >= 16 AND B/E >= 4), with the upstream's FILE AND FUNCTION named in the comment so the clone is auditable against the reference it mirrors. THE BOUNDARY IS NOT A TUNING THRESHOLD: a measured perf crossover would be ours to move; a kernel-family boundary is the upstream's, and inheriting the family's bits by construction is only valid INSIDE it — one row below the bound the answer is still correct in value but different in BITS, which is wrong for a verify round. THE FOLDED RUNG FACE (same file, the tuning axis of the same coupling): the MoE tile-plan ladder keyed on mean rows per expert records WHICH REFERENCE VERSION its rungs were measured against, verbatim (gather_qmm_nax.zig:22-25): '/// Tile configuration by mean rows per expert and K. The 96+-row rungs are ours: oMLX's seg tiles were measured against mlx 0.32.2, whose sorted kernel masked whole row blocks; 0.32.3 schedules row tiles itself and the plain db 96-row tile-on-x layout is the one that still beats it. The paired gate/up kernel keeps seg 128.' with the rungs themselves ('if (per_expert < 36 or (k < 1024 and per_expert < 120)) return .{ .sched = .db, .bm = 64, .bk = 64, .gx = 0, .pad = 0 };', gather_qmm_nax.zig:29, through the seg-128 top rung at :33) — when the upstream's own scheduling CHANGES between versions, the winning rung changes, so the ladder's validity is keyed to the reference version it was measured against and an upstream version bump re-opens the MEASUREMENT, not just the correctness. DECISION CONTENT: (a) find the upstream's own dispatch predicate for the kernel family you replace and copy it EXACTLY — the boundary belongs to the reference; (b) cite the upstream file + function in the comment (auditability when upstream moves); (c) the reason is BIT ORDER: the sibling 'sums in another order' — the clone is a correctness act for verify-round consumers, not a perf guard; (d) the same coupling on the tuning axis: tuned rungs against a reference carry the version they were measured against; a reference version bump re-opens both the correctness clone and the measured rungs. REGIME: drop-in kernels fronting a framework that dispatches among several order-different kernels (MLX quantized matmul / gather families); MoE gather where rows-per-expert selects the family; speculative-verify lanes that replay one-row steps against a wide call. ANTI-REGIME: an upstream with ONE kernel across the range (no order boundary to clone — any predicate is a pure perf crossover and ours to tune); consumers under tolerance gates (reassociation is legal there); upstreams whose dispatch predicate is private or unstable (pin the version). KINSHIP (do not double-count): fa-fast-path-validated-exact-shape-admission-v-as-strided-view (B208) owns validated-exact-SHAPE admission — the allowlist conjunct naming one measured-good shape in full; THIS owns CLONE-THE-UPSTREAM-PREDICATE — the boundary's PROVENANCE is the reference's own dispatch, never our measurement; dispatcher-eligibility-predicate-lags-kernel-capability (B103) owns deleting a stale conjunct (capability wider than the predicate); THIS owns mirroring a live boundary (the predicate is exactly as wide as the family, deliberately); batch-invariance-locks-reduction-geometry (B110) locks OUR geometry under a caller's contract; THIS borrows the UPSTREAM's boundary so no contract is needed; launch-heuristic-pinned-to-calibration-arch (B111) pins tuned thresholds to the calibrated SKU — the folded rung face is the same discipline one level up (tuned rungs pinned to the measured reference VERSION); dispatch-cliff-bitexact-shape-confinement (B115 addendum) confines dispatch inside a bit-proven width range once known; THIS prevents the cliff by inheriting the upstream's own family boundary. NotBenchable here (an admission boundary + a tile-ladder provenance law; the 96-row rung claims are the source's own measurements against mlx 0.32.2/0.32.3 — provenance, never a bar). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (gather_qmm_nax.zig:59-63 the law comment + predicate, :22-34 the tile-plan rungs + the version-keyed doc; every quote verbatim at the pin this session; file header: ported from oMLX omlx/patches/m5_gather_qmm_nax.py @ d6b2b92, Apache-2.0 lineage; repo MIT). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: the replacement admits by its OWN measured crossover —\n// \"fast from 8 rows\" — with no idea that below the framework's own\n// bound a DIFFERENT sibling kernel runs, summing in another order. A\n// verify round replaying one-row steps diverges from the wide call's\n// bits while every value stays tolerance-correct.\nfn admit_naive(batch_rows: usize, experts: usize) -> bool {\n    let _ = experts;\n    batch_rows >= 8 // OUR threshold: a perf crossover, not the family bound\n}".to_string(),
            opt_pattern: "// optimized: clone the UPSTREAM framework's own dispatch predicate\n// — `B >= 16 && B / E >= 4` (quantized.cpp GatherQMM::eval_gpu) — and\n// cite it in the comment; below that bound the framework runs\n// gather_qmv, which sums in another order, and MTP verify rounds must\n// keep its bits.\nfn admit_clone_upstream(batch_rows: usize, experts: usize) -> bool {\n    // Take only the calls MLX sends to its sorted row-block kernel.\n    batch_rows >= 16 && batch_rows / experts.max(1) >= 4\n}\n\n// the folded rung face: tuned tile rungs record the reference VERSION\n// they were measured against — an upstream scheduling change re-opens\n// the measurement (0.32.2 masked whole row blocks; 0.32.3 schedules\n// row tiles itself, and the plain db 96-row tile is the one that wins).\nfn plan_rung(per_expert: usize, k: usize, paired: bool) -> (u32, u32) {\n    if per_expert < 36 || (k < 1024 && per_expert < 120) {\n        (64, 64) // db 64x64 — the thin-fan-in rung\n    } else if k >= 1024 && per_expert < 48 {\n        (64, 64)\n    } else if k < 1024 || per_expert < 96 || !paired {\n        (96, 64) // db 96-row tile-on-x: measured vs mlx 0.32.3's scheduler\n    } else {\n        (128, 128) // seg 128 — the paired gate/up kernel keeps it\n    }\n}".to_string(),
        },
        // ── B: the row-count bit-invariance law — every split parameter
        // the summation order depends on keys on the WEIGHT's shape,
        // never the row count, so a drafted window verifies with the
        // one-row step's bits. ─
        KernelRule {
            rule_id: "row-count-invariant-bits-split-keyed-on-weight-shape".to_string(),
            gpu_concept: "MECHANISM (row-count bit-invariance through shape-only split geometry; category B — compute-order invariance contract): when a speculative-decode engine must VERIFY a drafted window bit-identically against the one-row steps it drafted from, EVERY split/threading parameter the kernel's floating-point summation order depends on must be derived from the WEIGHT's shape alone — never from the activation row count. THE LAW, verbatim in-source (lane_qmm.zig:7-9, the file header): '//! order; the slice count follows the weight's shape only. A row's bits never depend on how many rows ride with it, so a drafted window verifies with the one-row step's bits.' THE SPLIT FUNCTION, verbatim (lane_qmm.zig:350-356): '/// K slices for an (n, k) weight: fixed by the shape, never by the row count.' over 'fn splitK(n: c_int, k: c_int) c_int { const tiles = @divTrunc(n + 31, 32); var sk: c_int = 1; while (sk < 8 and tiles * sk < 1024 and @divTrunc(@divTrunc(k, 64), sk * 2) >= 8) sk *= 2; return sk; }' — the signature READS NO ROW COUNT: the function could not key on rows if it wanted to, and that is the design. The column-tile pick is the same law on a second axis, verbatim (lane_qmm.zig:358): '/// The pick follows the weight's shape only: 64-column tiles where N allows.' The sibling kernel states it as the ROUTER's public contract, verbatim (simd_qmm.zig:587-588): '/// `x [..., K] @ w.T` for 1..MAX_ROWS rows, or null outside the kernels.' / '/// A row's bits do not depend on how many rows ride with it.' with its own split function doc (simd_qmm.zig:399-401): '/// Chunks the K groups split into: a function of the shape only (it sets the bits). /// Capped at 16: `mma` runs S simdgroups per threadgroup, and a 1024-thread group exceeds what older GPUs grant this register-heavy kernel.' — '(it sets the bits)' names WHY the key must be shape-only: the split count determines the summation order. THE ENFORCEMENT ARM — the per-shape runtime bit-identity probe between the two kernel FAMILIES (one-row scalar vs many-row mma), verbatim (simd_qmm.zig:633-634): '/// Once per shape: whether one-row `scalar` calls give `mma`'s rows bit for bit on this GPU; where they do not, one-row calls of the shape take `mma`.' — prepare() draws one random 8-row input (seed 0x5eed), runs the mma family once, slices each row r out, runs the one-row scalar family on it, and compares with array_equal (bit-for-bit, never tolerance); on ANY mismatch the SHAPE is memoized — verbatim (simd_qmm.zig:671): 'if (!same_all) try mma_one_row.put(std.heap.c_allocator, shape, {});' — under the table declared, verbatim (simd_qmm.zig:435): '/// Shapes (n, k, bits) whose one-row calls take `mma`: there the scalar chain's bits differ.' THE PROBE'S SAFE DIRECTION is the load-bearing half: it never WIDENS an equivalence class — divergence only NARROWS the fast scalar kernel's admission (one-row calls routed to the family the many-row calls use), so a sampled probe is sound here exactly where a widening probe would not be. DECISION CONTENT: (a) the split count is a pure function of (n, k) — the row count never enters; the bit-ordering consequences (which lane/simdgroup sums which slice, the tree that combines them) are therefore row-invariant BY CONSTRUCTION, not by assertion; (b) row-side tiling may change with row count ONLY through parameters that provably never touch the summation order (per-row output tiles; rows past R copy row R-1 and are never stored — simd_qmm.zig:362-364's 'rows past R copy row R - 1'); (c) where two kernel FAMILIES share a router (one-row vs many-row), a once-per-shape probe compares the pair bit-for-bit at first use and routes the minority posture to the majority family — memoized per (n, k, bits), BEFORE any verify round depends on it; (d) the invariance is stated as the router's public contract in the entry-point doc, where the caller reads it. REGIME: speculative-decode verify lanes (a drafted window must verify against serial step bits); any multi-row kernel sharing a router with one-row kernels over the same weights; split-K / persistent kernels whose slice count could plausibly key on rows for occupancy. ANTI-REGIME: pure throughput paths under tolerance gates (row-dependent splits are legal there — the two-regime split by CONTRACT, not by size); probe evidence used to WIDEN classes (B193's finding — sampled output agreement cannot certify order-identity). KINSHIP (do not double-count): batch-invariance-locks-reduction-geometry (B110) locks OUR reduction geometry under a caller's cross-batch contract; THIS derives the geometry from the weight shape so NO contract is needed — the invariance is structural; fixed-order-interleaved-accumulator-epilogue (B180) is the in-kernel twin — its per-(row,col) sum order 'depends only on the weight shape, so a column gives the same bits for every column count'; THIS owns the HOST-side split/kernel-selection axis that decides which in-kernel order a call gets; dispatch-cliff-bitexact-shape-confinement (B115 addendum) confines dispatch inside a bit-proven width range once the cliff is known; THIS prevents the cliff from existing at the row axis by construction; construction-identity-row-classes-replace-probe (B193) owns probe soundness — 'a SAMPLED self-test cannot certify' order-identity in the WIDENING direction; THIS's prepare probe samples random inputs in the SAFE direction (divergence only narrows admission, never widens a class), which is why a one-draw probe suffices; the B213 rider on simdgroup-row-packing-reduction-amortization carries the same-bits row-independence note inside its packing contract — THIS owns the dispatch-side derivation. NotBenchable here (an invariance/admission contract; the route's own M5 numbers ride its header as provenance, never a bar). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (lane_qmm.zig:5-11 the header law, :350-356 splitK, :358-359 coopFor; simd_qmm.zig:399-404 splits, :435 mma_one_row, :587-588 the qmm contract, :633-672 the prepare probe; every quote verbatim at the pin this session; lane_qmm ported from TensorFold's lane_qmm.py/lane_widen.py per its header; repo MIT). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: the K-slice count keys on the ROW count (more rows -> more\n// slices for occupancy) — the same weight sums in a different slice\n// order at 1 row than at 8, so a drafted window cannot verify against\n// the one-row steps' bits without a tolerance gate.\nfn split_k_naive(n: usize, k: usize, rows: usize) -> usize {\n    let _ = n;\n    let mut sk = 1;\n    while sk < 8 && rows / sk >= 64 && k / (sk * 2) >= 64 {\n        // keyed on ROWS: the slice count moves with the batch, and the\n        // summation order moves with it\n        sk *= 2;\n    }\n    sk\n}".to_string(),
            opt_pattern: "// optimized: the slice count is a pure function of the WEIGHT's\n// shape (n, k) — 'the slice count follows the weight's shape only.\n// A row's bits never depend on how many rows ride with it' — and a\n// per-shape probe routes one-row calls to the family whose bits the\n// many-row calls carry when the pair ever differs.\nfn split_k(n: usize, k: usize) -> usize {\n    let tiles = (n + 31) / 32;\n    let mut sk = 1;\n    while sk < 8 && tiles * sk < 1024 && (k / 64) / (sk * 2) >= 8 {\n        sk *= 2; // keyed on (n, k) only — never the row count\n    }\n    sk\n}\n\n// the per-shape probe (once per (n, k, bits), at first use): run the\n// many-row family once, slice each row out, run the one-row family,\n// compare bit-for-bit; on ANY mismatch the shape's one-row calls take\n// the many-row family — divergence only NARROWS, never widens.\nfn probe_one_row_bits(\n    run_many: impl Fn(&[f32]) -> Vec<f32>,\n    run_one: impl Fn(&f32) -> f32,\n    x8: &[f32; 8],\n) -> bool {\n    let full = run_many(&x8[..]); // the 8-row call, once\n    let mut same_all = true;\n    for r in 0..8 {\n        let one = run_one(&x8[r]); // the one-row family on row r\n        let fr = full[r]; // row r of the many-row call\n        if one.to_bits() != fr.to_bits() {\n            same_all = false; // bit-for-bit, not tolerance\n        }\n    }\n    same_all\n}".to_string(),
        },
        // ── D: the threadgroup-cap halving law — the device's cap error
        // halves the simdgroups, memoized per config; bit-safe ONLY
        // because the chunks walked sum in the same order. ─
        KernelRule {
            rule_id: "threadgroup-cap-halving-with-order-preserving-sum".to_string(),
            gpu_concept: "MECHANISM (device threadgroup-cap compliance via order-preserving simdgroup halving; category D — launch-geometry adaptation): when a register-heavy kernel's threadgroup exceeds what the device grants, catch the launch failure carrying the device's own words ('Thread group size'), HALVE the simdgroups per threadgroup, rebuild the plan, and MEMOIZE the halved count per config key — the halving is BIT-SAFE only because the S K-chunks walked by fewer simdgroups sum in the same order, and an in-tree test pins that property. THE MEMO TABLE'S LAW, verbatim (simd_qmm.zig:429-432): '/// Simdgroups per `mma` threadgroup by (n, k, bits, rt) where fewer than S fit: /// Metal caps a register-heavy kernel's threadgroup (M1/M2: 448 for this one), and the S chunks walked by fewer simdgroups sum in the same order.' over 'var mma_sg: std.AutoHashMapUnmanaged([4]c_int, c_int) = .{};' — the key is the FULL config tuple (n, k, bits, row-tiles), so the next plan of the same config launches halved directly: one failed launch per config per process. THE TRIGGER IS THE ERROR, NOT A CAPABILITY QUERY, verbatim (simd_qmm.zig:567-568): '// A new mma plan runs once here: where Metal caps this kernel's threadgroup below S simdgroups, halve them and rebuild.' with the guard, verbatim (simd_qmm.zig:573): 'if (e != error.MlxError or cur <= 1 or !mlx.takeErrorIf(\"Thread group size\")) return e;' — only that exact error string and only above the floor adapt; EVERYTHING ELSE RE-RAISES. The halve-and-memoize pair, verbatim (simd_qmm.zig:574-576): 'try mma_sg.put(std.heap.c_allocator, sgk, @divTrunc(cur, 2));' then forgetPlan + 'log.info(\"[simd_qmm] mma n={d} k={d} bits={d}: {d} simdgroups per threadgroup on this GPU\\\\n\", ...)' — the adaptation is LOUD (logged with the config) and PERSISTED (the memo). THE BIT-SAFETY ARGUMENT IS THE LICENSE, AND IT IS TESTED: each simdgroup serially walks the chunks it owns — the MMA body's chunk loop is 'for (int g = c; g < G; g += S)' (simd_qmm.zig:255) — so halving S changes only the chunk-to-simdgroup assignment while the per-chunk arithmetic and each simdgroup's serial chain are untouched, and the in-tree test named, verbatim (simd_qmm.zig:688): 'test \"simd_qmm: mma over half the simdgroups per threadgroup gives the same bits\"' — the same-bits claim is an assertion, not a hope. DECISION CONTENT: (a) adapt on the DEVICE'S OWN ERROR STRING, at first occurrence, on a FRESH plan — a capability query would have to know every cap rule the driver applies (M1/M2's 448 for this register-heavy shape is a fact the error teaches you); (b) the halving carries a FLOOR (cur <= 1 re-raises) — never divide below one simdgroup, never loop forever; (c) memoize per the FULL config tuple so the cost is one failed launch per config per process — and the memo's verdict travels to every later plan of the same key; (d) the halving is legal ONLY where the summation order is preserved by the serial chunk-walk structure — and a test pins it; without that property the halving is a numerics change, not an adaptation. REGIME: register-heavy Metal/CUDA kernels whose threadgroup size lands above device caps on SOME configs (older or smaller GPUs); kernels whose parallel decomposition is a serial chunk walk per worker (the halving lengthens each walk, it never reorders the combine); speculative-verify lanes where the same-bits property is load-bearing. ANTI-REGIME: kernels whose cross-chunk combine reassociates when the chunk count per worker changes (the halving then moves bits — refuse or re-verify); capability queries that ARE available and precise (prefer the query; the error-triggered path is for caps the API will not tell you); per-call adaptation without the memo (one failed launch per CALL is waste). KINSHIP (do not double-count): chunk-downsize-work-stealing-microtile-floor (B187) owns halve-with-a-floor GRAIN selection driven by core saturation (throughput); THIS owns halve-on-CAP-FAILURE driven by the device's refusal, whose justification is ORDER preservation (bits), not occupancy — the trigger and the safety argument both differ; the B213 rider on simdgroup-row-packing-reduction-amortization carries the occupancy-guarded CTA shrink ('while (num_warps > 1 && ... < nsm) { num_warps /= 2; }') — a THROUGHPUT halve with a floor; THIS is a COMPLIANCE halve keyed on the error, memoized per config; row-count-invariant-bits-split-keyed-on-weight-shape (this slice) owns the shape-only split DERIVATION that makes the halving bit-safe in the first place — compose: derive splits from the weight shape, then halve the workers under the device cap with the order preserved; captured-graph-init-unconditional-and-stream-ordered (B110) owns graph-capture error handling — THIS owns runtime plan-rebuild adaptation. NotBenchable here (a launch-adaptation mechanism; no perf number rides the law — the halving recovers capability, and the same-bits test is the instrument, not a timing row). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (simd_qmm.zig:429-432 the memo law, :553-580 the retry loop — :567-568 the comment, :573 the error-string guard, :574-576 the halve + forget + log, :688 the same-bits test, :255 the serial chunk walk it rests on; every quote verbatim at the pin this session; repo MIT — simd_qmm ported from TensorFold's simd_qmm.py per its header). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: the threadgroup is sized for the full S-simdgroup plan; on\n// a device that caps the group below that, the launch FAILS and the\n// failure propagates as a hard error — one capped config takes the\n// whole route down, and every later call of the same config fails\n// again.\nfn launch_naive(simdgroups: usize, apply: impl Fn(usize) -> Result<(), String>) -> Result<(), String> {\n    apply(simdgroups) // a hard error: no adaptation, no memo, no floor\n}".to_string(),
            opt_pattern: "// optimized: on the FIRST run of a fresh plan, a launch error whose\n// text carries the device's own words ('Thread group size') halves\n// the simdgroups, rebuilds, and memoizes the halved count per\n// (n, k, bits, row_tiles) — bit-safe ONLY because each simdgroup\n// serially walks the chunks it owns (g = c; g < G; g += S), so the\n// halving moves the chunk assignment, never the sum order; a floor at\n// 1 re-raises everything else.\nuse std::collections::HashMap;\n\nfn launch_cap_adaptive(\n    cfg: (i32, i32, i32, i32), // (n, k, bits, row_tiles)\n    memo: &mut HashMap<(i32, i32, i32, i32), usize>,\n    apply: impl Fn(usize) -> Result<(), String>, // one launch attempt\n    default_splits: usize,\n) -> Result<usize, String> {\n    let mut sg = *memo.get(&cfg).unwrap_or(&default_splits);\n    loop {\n        match apply(sg) {\n            Ok(()) => {\n                // memoized: one failed launch per config, ever\n                memo.insert(cfg, sg);\n                return Ok(sg);\n            }\n            Err(e) => {\n                let is_threadgroup_error = e.contains(\"Thread group size\");\n                if sg <= 1 || !is_threadgroup_error {\n                    return Err(e); // anything else re-raises; the floor holds\n                }\n                sg /= 2; // fewer simdgroups walk the S chunks in the same\n                         // order — pinned by the same-bits test\n            }\n        }\n    }\n}".to_string(),
        },
        // ── D: the runtime-canary admission law — a fast kernel admits
        // itself per config only after a synthetic-workload bit-compare
        // vs stock, with a regime-keyed oracle and latch hygiene. ─
        KernelRule {
            rule_id: "canary-admission-per-config-bit-equal-stock".to_string(),
            gpu_concept: "MECHANISM (runtime synthetic-workload canary admission; category D — dispatch admission by runtime bit-compare): a replacement kernel serving a stock op's shapes admits itself per CONFIGURATION KEY only after a synthetic-workload CANARY compares its output against the stock op's on the same inputs — run at first use inside a live forward, cached per key (positive AND negative), disable-with-log naming every config axis on mismatch — and the ORACLE IS REGIME-KEYED: bit-equality against stock only where stock is CORRECT; where the stock reference itself has a known bug, the oracle becomes a dequantized fp32 product under a peak-relative bar, never a bit-compare against a broken reference. THE KEY, verbatim (gather_qmm_nax.zig:9): 'const CanaryKey = struct { plan: Plan, bits: u32, group: u32, align_n: bool, align_k: bool, mx: bool };' — every axis that changes the compiled kernel or launch geometry; the verdict table 'var canaries: std.AutoHashMapUnmanaged(CanaryKey, bool) = .{};' (:15) caches both directions, and a verdict NEVER crosses configs. THE SYNTHETIC WORKLOAD, verbatim (gather_qmm_nax.zig:238): 'const counts = [_]u32{ 70, 0, 5, 33, 64, 17, 140, 11 };' — the per-expert row counts are ragged ON PURPOSE (an empty expert, a 5-row, a 33-row, a 140-row): the canary must exercise the tile scan's edge classes, not the median shape. THE REGIME-KEYED ORACLE, verbatim (gather_qmm_nax.zig:277): '// Stock NAX reads stale activations in a K tail: compare against a dequantized fp32 product there.' — below K % 64 == 0 the REFERENCE is the broken one, so the canary switches oracles: bit-equality against stockGather where stock is sound, and where it is not, floatReferenceClose — '/// `got` against a dequantized fp32 gather-matmul, within 1/64 of the reference's peak.' (:291) with the bar, verbatim (:312, :341): '/// max |got - ref| within 1/64 of ref's peak.' over 'return std.math.isFinite(err) and err <= scale / 64;' — a RELATIVE bar (1/64 of the reference's own peak magnitude), never an absolute tolerance that a large-magnitude output would trivially pass or a small one trivially fail. THE ERROR-LATCH HYGIENE (the subtle half), verbatim (gather_qmm_nax.zig:345-346): '// The canary runs inside a prefill forward: an error an earlier op latched belongs to that forward and must reach its `checkError`, so drop only a latch the canary raised.' — 'const had_error = mlx.errorPending();' is recorded BEFORE the canary runs, and on canary failure 'mlx.dropLatchedErrorUnless(had_error);' (:349) drops the latch ONLY IF the canary raised it: a diagnostic running inside a live forward must not swallow the enclosing forward's own errors. THE DISABLE-WITH-LOG, verbatim (gather_qmm_nax.zig:353): 'if (!ok) log.warn(\"[gather-nax] disabled for {d}-bit group={d} {s} bm={d} bk={d} aligned-N={any} aligned-K={any}: canary mismatch\\\\n\", ...)' — the log names the config's every axis, so a disabled config is diagnosable from the log alone; and the negative caches (:352 'canaries.put(std.heap.c_allocator, key, ok) catch return false;') — one canary per config per process, never retried per call. DECISION CONTENT: (a) admission is per FULL config key — plan + bits + group + both alignment flags + format family; (b) the workload is synthetic but STRUCTURALLY adversarial (ragged expert counts hitting the scan's edge classes); (c) the oracle's regime split is the honesty core: bit-compare against the reference where the reference is sound; where the reference is itself buggy in a known regime, compare against a BETTER reference with a relative bar sized to that reference's precision (fp32-dequant product, 1/64-of-peak) — never a bit-compare against a broken oracle, never an unconditioned tolerance; (d) failure disables with the full config in the log and caches NEGATIVE — one canary per config per process; (e) the canary runs inside a live forward, so record the pending-error state first and drop only your own latch. REGIME: drop-in accelerators for stock ops across configs the stock also serves (MoE gather shapes, per-arch JIT kernels); first-use admission where load-time exhaustive enumeration is impossible (the domain is shapes + data, not a 16-bit dtype). ANTI-REGIME: enumerable domains (a 16-bit input domain admits by EXHAUSTIVE enumeration — B195's gate is strictly stronger than any sample); bit-comparing against a reference known buggy in the regime under test (that is what the regime-keyed oracle exists to prevent); per-call canaries (the cache is the design — a per-call compare would cost more than the kernel it guards). KINSHIP (do not double-count): enumerable-domain-bit-identity-admission-gate (B195, entries_gpu_63) is the ENUMERABLE twin — load-time exhaustive sweep, binary cached verdict, 'self-test failed; original kept'; THIS is the runtime-canary face for domains that cannot enumerate (synthetic workload vs stock, per-config key); exhaustive-domain-input-patch-bit-identity (B115) enumerates to PATCH divergent inputs so a fusion survives; THIS samples to ADMIT-or-REFUSE whole configs, no patching; construction-identity-row-classes-replace-probe (B193) owns probe soundness — sampled outputs cannot certify order-identity for WIDENING; THIS's canary never widens anything (mismatch only disables), the safe direction; degrade-not-fail-load-qualification-probe (rust_perf B219) owns load-time two-class admission with loud disable — the load-time rust_perf twin of this first-use gate; reduction-restructure-needs-source-owned-comparator (B95) owns comparator choice for restructured reductions — the regime-keyed oracle here (bit-equal where the reference is sound, fp32-dequant + peak-relative bar where it is not) is the comparator-honesty face for a BUGGY reference, a class B95 does not reach. NotBenchable here (an admission instrument; the win it licenses is measured elsewhere — the canary's own cost is one launch per config per process, and no perf number rides the law). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (gather_qmm_nax.zig:9,:17 the key + verdict caches, :237-282 the canary + the ragged counts, :277 the regime-keyed-oracle comment, :284-290 stockGather, :291-311 floatReferenceClose, :312-341 withinPeak, :343-355 armed — the latch comment :345-346, dropLatchedErrorUnless :349, the cache :352, the disable log :353; every quote verbatim at the pin this session; file header: ported from oMLX @ d6b2b92, Apache-2.0 lineage; repo MIT). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: the replacement is admitted by static shape checks alone\n// — a config where stock and the replacement disagree in bits serves\n// wrong answers silently; and a canary failure that leaks its error\n// latch poisons the enclosing forward's own error reporting.\nfn admit_static(bits: u32, group: u32, k: usize, n: usize) -> bool {\n    bits == 4 && (group == 32 || group == 64) && k % 32 == 0 && n % 64 == 0\n    // shape-legal != bit-equal: no comparison ever ran\n}\n\nfn run_canary_naive(fast: impl Fn() -> Result<Vec<f32>, String>) -> bool {\n    match fast() {\n        Ok(_) => true,   // a bit-compare against stock never happened\n        Err(_) => false, // and the latched error — ours or an earlier\n                         // op's — is swallowed together\n    }\n}".to_string(),
            opt_pattern: "// optimized: per-CONFIG canary — a synthetic ragged workload,\n// bit-compare vs stock where stock is sound, an fp32-dequant oracle\n// with a peak-relative bar where stock itself is buggy, a cached\n// verdict (one per config, both directions), disable-with-log naming\n// every config axis, and error-latch hygiene: drop only a latch the\n// canary raised.\nuse std::collections::HashMap;\n\n#[derive(PartialEq, Eq, Hash, Clone, Copy)]\nstruct CanaryKey {\n    plan: u32,\n    bits: u32,\n    group: u32,\n    align_n: bool,\n    align_k: bool,\n}\n\nfn canary_counts() -> [u32; 8] {\n    // ragged on purpose: an empty expert, a 5-row, a 33-row, a 140-row\n    [70, 0, 5, 33, 64, 17, 140, 11]\n}\n\nfn stock_is_sound(k: usize) -> bool {\n    k % 64 == 0 // below this, stock NAX reads stale activations in a K tail\n}\n\nfn within_peak(got: &[f32], reference: &[f32]) -> bool {\n    // max |got - ref| within 1/64 of ref's peak — the bar for the\n    // regime where the bit-reference itself is broken\n    let mut max_delta = 0.0f32;\n    let mut max_ref = 0.0f32;\n    for (g, r) in got.iter().zip(reference) {\n        max_delta = max_delta.max((g - r).abs());\n        max_ref = max_ref.max(r.abs());\n    }\n    max_delta.is_finite() && max_delta <= max_ref / 64.0\n}\n\nfn armed(\n    key: CanaryKey,\n    k: usize,\n    cache: &mut HashMap<CanaryKey, bool>,\n    run_fast: impl Fn() -> Result<Vec<f32>, String>,\n    stock: impl Fn() -> Vec<f32>,\n    dequant_ref: impl Fn() -> Vec<f32>,\n    error_latched_before: bool,\n    drop_latched_error: impl Fn(bool),\n) -> bool {\n    if let Some(ok) = cache.get(&key) {\n        return *ok; // one canary per config per process\n    }\n    let ok = match run_fast() {\n        Ok(got) => {\n            if stock_is_sound(k) {\n                // bit-equal where the reference is sound\n                got.iter().map(|v| v.to_bits()).zip(stock().iter().map(|v| v.to_bits())).all(|(a, b)| a == b)\n            } else {\n                within_peak(&got, &dequant_ref()) // peak-relative elsewhere\n            }\n        }\n        Err(_) => {\n            // drop only a latch the canary raised — an earlier op's\n            // latched error must still reach the forward's checkError\n            drop_latched_error(!error_latched_before);\n            false\n        }\n    };\n    cache.insert(key, ok); // negative caches too: never retried per call\n    ok\n}".to_string(),
        },
        // ── D: the toolchain-gap negative law — a measured-slower form
        // ships as an admission refusal naming the missing capability
        // and the exact event that re-opens the measurement. ─
        KernelRule {
            rule_id: "prompt-form-refused-toolchain-format-gap-reopen-trigger".to_string(),
            gpu_concept: "MECHANISM (a measured negative ships as an admission refusal with a named reopen trigger; category D — dispatch admission + the negative-row doctrine): a kernel form that measured SLOWER than stock is kept out of the tree, and the refusal — living in the ADMISSION FUNCTION'S OWN DOC, where the next implementer looks — carries three legs: the MEASUREMENT (what lost, on which shapes), the ROOT CAUSE (a missing TOOLCHAIN capability, not a tuning gap), and the REOPEN TRIGGER (the exact capability whose appearance re-opens the test). THE FULL NEGATIVE ROW, verbatim (qmv_nax2.zig:330-339, the formFor doc): '/// Above 16 rows this declines and stock keeps prompt width. A 64x64-tile prompt form was built and MEASURED at 0.87-0.93x stock on all four projection shapes at M 128..2048 (0.55-0.75x with two row subtiles per threadgroup), so it is not in the tree. The reason is the toolchain: this host's Metal has `uint4b_format` but no `uint2b_format`, so a prompt tile has to expand the stored 2-bit words to 4-bit codes in threadgroup memory first, and that costs more than stock's own tiled `qmm` saves. The engine this route came from avoids the expansion with `uint2b_format`, and its expanding variant pays for the staging by quantizing the activation to int8 -- which is not lossless. Re-test if `uint2b_format` ever appears.' THE DECLINES IT GUARDS, verbatim (qmv_nax2.zig:341-345): 'if (bits != 2 or group_size != 128) return .decline;' / 'if (!nax) return .decline;' / 'if (m < MIN_ROWS) return .decline;' / 'if (m > narrowMaxRows()) return .decline;' / 'if (@rem(k, 128) != 0 or @rem(n, 32) != 0) return .decline;' — the row-count ceiling decline is the one the negative row explains ('Above 16 rows this declines and stock keeps prompt width'), and the file header points at it, verbatim (qmv_nax2.zig:8-9): '//! Prompt width stays on stock — see `formFor` for the prompt-form measurement and why it is not here.' THE THREE LEGS DECOMPOSED: (1) the measurement names its full envelope (0.87-0.93x across ALL FOUR projection shapes at M 128..2048, plus the WORSE sub-variant 0.55-0.75x with two row subtiles — the negative discloses its own failed alternatives); (2) the cause is a CAPABILITY GAP with its cost mechanism spelled out: without `uint2b_format` a prompt tile must expand stored 2-bit words to 4-bit codes in threadgroup memory FIRST, and that staging 'costs more than stock's own tiled `qmm` saves' — the loss is structural to the toolchain, not to the tiling; (3) the NOT-LOSSLESS ESCAPE IS ALSO REFUSED, and named: the originating engine's expanding variant 'pays for the staging by quantizing the activation to int8 -- which is not lossless' — a bit-exactness bar excludes the workaround, so the negative row's scope is explicitly the LOSSLESS lane; and the trigger is the CAPABILITY ITSELF — 'Re-test if `uint2b_format` ever appears' — not a calendar, not a perf margin. DECISION CONTENT: (a) a refusal with a reopen trigger has three legs — measurement, cause, trigger; without the cause the row reads 'slower, don't try'; without the trigger, the capability arriving changes nothing; (b) the row lives in the admission function's doc (the place formFor's next editor reads), with the file header pointing at it — a negative buried in a changelog is a negative nobody re-tests; (c) discloses its own failed sub-variants (the two-row-subtile 0.55-0.75x) so the next attempt does not re-try them blind; (d) the lossless bar participates in the refusal: an available lossy workaround is named AND excluded, scoping the negative to what it actually measured. REGIME: admission functions gating forms measured against a stock baseline on a fixed toolchain (Metal tensor-op formats, instruction availability, driver capabilities); anywhere a toolchain update could flip a capability probe and with it the measured verdict. ANTI-REGIME: losses whose cause is TUNING (a crossover a better tile could move — that is a normal perf row, not a toolchain-gap row; the reopen would be a mechanism change, not a capability arrival); lossy-is-acceptable lanes (there the named escape IS the fix — record it as an adoption, not a refusal). KINSHIP (do not double-count): byte-cut-loses-when-plateau-is-issue-bound (B108, entries_gpu_21) owns the REFUTATION-TYPE row — the honest-loser tradition, 'the rule exists to STOP the plausible port' — and its reopen is a MECHANISM change (bandwidth-bound path, native narrow operand); THIS's reopen is a TOOLCHAIN CAPABILITY (a named format appearing in the shader language) — different trigger class, same doctrine; the B204 rider on swar-lane-widened-base3-dp4a-dot ('alias it back to generic until a validated replacement lands' — the NEON negative held behind a validation trigger, later lifted at B211 when the i8mm arm validated) is the closest kin and the precedent for capability-keyed re-arms; tile-shrink-occupancy-pays-feed-economics (B149) carries 'bounded reopen conditions are part of the rule'; fa-fast-path-validated-exact-shape-admission (B208) owns admission allowlists — THIS owns the DECLINE that keeps stock, with its reason and trigger in the doc. NotBenchable here (the row IS a negative measurement — 0.87-0.93x stock on the source's M5 shapes is provenance, never a bar; our lane would re-measure only at the reopen trigger, on our silicon). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (qmv_nax2.zig:326-339 the formFor doc — the measurement, the toolchain cause, the not-lossless escape, the reopen trigger; :340-347 the declines; :8-9 the header pointer; every quote verbatim at the pin this session; route ported from Layr-Labs/mlxfast-bonsai2-27b-engine per its header; repo MIT). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: the prompt-width form is declined with a bare number, or\n// not even that -- \"slower, don't\" -- and the reason it lost (the\n// missing tensor-op format that forced a threadgroup expansion)\n// leaves with the experiment. When the format ships in a toolchain\n// update, nothing re-opens the question, and the next session re-try\n// is blind.\nenum Form {\n    Decline,\n    Narrow,\n}\n\nfn form_for_naive(m: usize) -> Form {\n    if m > 16 {\n        Form::Decline // \"measured slower once\" -- no cause, no trigger\n    } else {\n        Form::Narrow\n    }\n}".to_string(),
            opt_pattern: "// optimized: the decline carries the measurement, the TOOLCHAIN\n// cause, the refused lossy escape, and the reopen trigger -- all in\n// the admission fn's doc, where the next implementer looks.\nenum Form {\n    Decline,\n    Narrow,\n}\n\n/// Above 16 rows this declines and stock keeps prompt width. A\n/// 64x64-tile prompt form was built and MEASURED at 0.87-0.93x stock\n/// on all four projection shapes at M 128..2048, so it is not in the\n/// tree. The reason is the toolchain: this host's Metal has\n/// `uint4b_format` but no `uint2b_format`, so a prompt tile has to\n/// expand the stored 2-bit words to 4-bit codes in threadgroup memory\n/// first, and that costs more than stock's own tiled qmm saves. The\n/// int8-activation escape is not lossless and is refused. Re-test if\n/// `uint2b_format` ever appears.\nfn form_for(m: usize, min_rows: usize, max_rows: usize, k: usize, n: usize) -> Form {\n    if m < min_rows || m > max_rows {\n        return Form::Decline; // stock keeps prompt width above the ceiling\n    }\n    if k % 128 != 0 || n % 32 != 0 {\n        return Form::Decline; // the kernel's own shape contract\n    }\n    Form::Narrow\n}\n\n// the reopen trigger is a capability probe, not a calendar: when the\n// missing format appears, the measured negative is re-run as-is.\nfn reopen_due(toolchain_has_uint2b_format: bool) -> bool {\n    toolchain_has_uint2b_format\n}".to_string(),
        },
        // ── K: the per-generation plan-table law — each measured GPU
        // generation carries its own rungs; a generation nobody measured
        // keeps the conservative arm by an explicit membership test. ─
        KernelRule {
            rule_id: "per-generation-plan-table-unmeasured-generation-fallback".to_string(),
            gpu_concept: "MECHANISM (per-GPU-generation measured plan table with an unmeasured-generation fallback; category K — autotune dispatch): a kernel-family plan (which geometry serves which row count) is a TABLE keyed on the GPU generation, built from kernel sweeps against stock on the league model's shapes — and a generation NOBODY measured keeps the conservative LEGACY arm via an explicit membership test, never an extrapolated rung: measured optima are facts about the GPU family they were swept on, and an unlisted generation inherits nothing. THE TABLE DOC, verbatim (qmv2.zig:210-212): '/// Per GPU generation (`applegpu_gNN`), from kernel sweeps over the Bonsai 27B shapes against stock at M = 1..8; a generation nobody measured keeps `legacy`. /// Below 2048 output rows too few threadgroups stream K and stock wins.' — the sweep shapes are OUR league model's (Ternary-Bonsai-2-27B, the serving class this corpus tracks), and the doc states the fallback as the table's own law. THE MEMBERSHIP TEST, verbatim (qmv2.zig:216-218): 'const measured = gen == 13 or gen == 16 or gen == 17;' / 'if (!measured) return .legacy;' / 'if (n < 2048) return .stock;' — three distinct refusals in four lines: unmeasured generation -> legacy (the conservative arm), narrow output -> stock (the too-few-threadgroups refusal: 'Below 2048 output rows too few threadgroups stream K and stock wins'), and the phone carve-out above ('if (phone) return .legacy;'). THE PER-RUNG DOCS CARRY THEIR OWN MEASUREMENT CONTEXT, verbatim (qmv2.zig:206-207): '/// M4 (g16) from 5 rows: the MMA kernel is flat to 8 rows and ~1.7x qmv2 at 8, ~1.6x stock at 16 (Bonsai 27B shapes); below 5, qmv2 is cheaper.' and the in-table refusal comment (:222): '// Stock wins at M = 5, and at M = 1 on anything narrower than the MLP.' — every rung and every refusal is a recorded measurement with its regime named, so a reader can tell MEASURED rows from DERIVED ones. THE TABLE IS THE SINGLE SOURCE FOR VERIFY-WIDTH QUESTIONS TOO, verbatim (qmv2.zig:233-234): '/// Whether generation `gen` verifies an 8-row window of a 2-bit ternary weight on the MMA lane, where it costs about what 5 rows do.' — mmaVerifiesWide consults planFor at the verify shape instead of re-deriving a threshold: one table answers throughput plans AND speculative-verify geometry. DECISION CONTENT: (a) the key is the GPU GENERATION (applegpu_gNN), not a model name or a capability bit — the measured optimum is a fact about the silicon family; (b) unmeasured -> the conservative arm by an EXPLICIT membership test (the rungs for g13/g16/g17 are listed by number) — an unlisted generation never inherits a neighbor's plan, and adding a generation means adding a measured row, not widening a predicate; (c) shape-level refusals live INSIDE the table as measured rows (n < 2048 -> stock, with the mechanism named: too few threadgroups stream K); (d) each rung's doc carries its own sweep context (which generation, which shapes, which multiples); (e) verify-lane questions route through the SAME table — a second threshold derived elsewhere would drift from the first. REGIME: kernel-geometry dispatch on consumer-GPU families that arrive faster than anyone can re-sweep (Apple gNN generations); league-model serving where the sweep shapes ARE the serving shapes; any plan choice where an unmeasured key would otherwise silently take a tuned arm. ANTI-REGIME: a single-silicon target (no table needed); shapes outside the swept class (the table's refusals are shape-scoped — B104's family-representative inheritance handles the outside); a future generation that PROVABLY matches an old one's silicon (still add the measured row — the cheap wrong answer is the extrapolated one). KINSHIP (do not double-count): launch-heuristic-pinned-to-calibration-arch (B111) shares the premise (thresholds are facts about the SKU they were calibrated on) and its remedy is the NO-SWEEP guardrail (gate the tuned ladder to the calibration arch, leave the rest on baseline); THIS is the multi-generation TABLE — every measured generation carries its OWN rungs, and the fallback is a real kernel choice (legacy), not merely a baseline constant; vendor-keyed-reduction-lane-partition-subgroup-request (B192) is the vendor-keyed twin (per-vendor arms + a resource-derived default for the un-measured); THIS keys on GPU GENERATION within one vendor, with the explicit measured-membership list as the law; swept-shape-bucket-launch-tables + no-harm-bucket-representative (B104) own the sweep-infrastructure upgrade path (offline-generated per-SKU tables with representative inheritance and worst-case-regret rows); the B170 rider on simdgroup-row-packing-reduction-amortization owns the ROW-COUNT-keyed measured table (kL) — THIS keys on DEVICE GENERATION with the unmeasured fallback as the decision content; warm-reachable-dispatch-signatures-before-timed-window (B115) owns warming the reachable variant set — orthogonal (this table decides WHICH variant, that rule compiles it before the window). NotBenchable here (the table IS the artifact of the source's sweeps — the ~1.7x/~1.6x rows are their M-family numbers on Bonsai 27B shapes, provenance never a bar; a fixture here would time a host lookup, not the kernel plans). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (qmv2.zig:206-207 the g16 rung doc, :210-212 the table doc, :213-230 planFor — the measured membership test :216, the legacy fallback :217, the n<2048 stock refusal :218, the per-generation rungs and the :222 refusal comment; :233-235 mmaVerifiesWide; every quote verbatim at the pin this session; repo MIT — the file's decode lineage cites @sudoingX's CUDA small-batch PTQ1_0 kernels, PrismML-Eng/llama.cpp#218). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: ONE rung ladder applied to every generation — the optimum\n// measured on the newest silicon silently serves generations nobody\n// swept, and an unmeasured generation inherits a neighbor's plan with\n// no trace in the code of which rows were ever measured.\nenum Plan {\n    Stock,\n    Legacy,\n    Rows4x2,\n    Mma,\n}\n\nfn plan_for_naive(m: usize, n: usize) -> Plan {\n    if n < 2048 {\n        return Plan::Stock;\n    }\n    if m >= 5 {\n        return Plan::Mma; // measured on g16 only — served to ALL gens\n    }\n    Plan::Rows4x2\n}".to_string(),
            opt_pattern: "// optimized: the plan is a TABLE keyed on GPU generation; a\n// generation nobody measured keeps the conservative LEGACY arm via an\n// explicit membership test — never an extrapolated rung — and every\n// refusal inside the table is a recorded measurement.\nenum Plan {\n    Stock,\n    Legacy,\n    Rows4x2,\n    Rows2x8,\n    Mma,\n}\n\nfn plan_for(gen: u32, phone: bool, m: usize, n: usize, k: usize) -> Plan {\n    if m < 1 || m > 16 {\n        return Plan::Stock;\n    }\n    if phone {\n        return Plan::Legacy; // phones keep the legacy arm outright\n    }\n    let measured = gen == 13 || gen == 16 || gen == 17;\n    if !measured {\n        return Plan::Legacy; // a generation nobody measured keeps legacy\n    }\n    if n < 2048 {\n        // below 2048 output rows too few threadgroups stream K\n        return Plan::Stock;\n    }\n    match gen {\n        13 => Plan::Rows4x2,\n        16 => {\n            if m >= 5 {\n                Plan::Mma // flat to 8 rows; ~1.7x qmv2 at 8 (g16 sweep)\n            } else if m == 1 {\n                Plan::Rows2x8\n            } else if m % 2 == 1 {\n                Plan::Rows4x2\n            } else {\n                Plan::Rows2x8\n            }\n        }\n        _ => {\n            // Stock wins at M = 5, and at M = 1 on anything narrower\n            // than the MLP.\n            if m == 5 || (m == 1 && n < 16384) {\n                Plan::Stock\n            } else if m == 3 || k >= 16384 {\n                Plan::Rows4x2\n            } else {\n                Plan::Rows2x8\n            }\n        }\n    }\n}\n\n// the table answers VERIFY-width questions too: an 8-row window\n// rides the MMA lane where it costs about what 5 rows do.\nfn mma_verifies_wide(gen: u32, phone: bool) -> bool {\n    matches!(plan_for(gen, phone, 8, 17408, 5120), Plan::Mma)\n}".to_string(),
        },
        // ── A: the quad-lane line-load law — the quad co-loads a
        // contiguous line one aligned uint4 per lane and takes each
        // other's words back with simd_shuffle; a 2-deep ring keeps
        // one block in flight. ─
        KernelRule {
            rule_id: "quad-lane-line-load-shuffle-word-exchange-ring".to_string(),
            gpu_concept: "MECHANISM (fragment-quad cooperative line loading with shuffle word exchange; category A — memory access): when each lane's data need is a few BYTES of a CONTIGUOUS line that its whole fragment quad collectively consumes, do NOT load by need — assign the line's WORDS to the quad's lanes positionally (one aligned 16-byte uint4 each, so the quad's four loads cover the whole 64-byte line at full vector width) and recover the bytes each lane's fragment actually needs from its siblings with simd_shuffle, the exchange permutation DERIVED from the fragment coordinate map; a 2-deep register ring keeps one block in flight while the current one is consumed. THE LAW, verbatim (qmv_nax2.zig:59-64): '/// A 256-k block is one contiguous 64-byte line of each weight row, so the four lanes of a fragment quad load it between them and take each other's words back with `simd_shuffle`; one block stays in flight ahead of the one being consumed. Every 16-k step dequantizes into the tensor unit's right operand and runs a 16x32x16 multiply-accumulate, so the codes never land in memory and the affine scale is already in the product.' THE FRAGMENT COORDINATE the permutation derives from, verbatim (qmv_nax2.zig:87-93): '// Fragment coordinate of this lane (BaseNAXFrag::get_coord): elements 0..3 sit at (fm, fn..fn+3), elements 4..7 at (fm + 8, fn..fn+3).' with the coordinate math 'const short fm = ((qid & 4) | short((simd_lid >> 1) & 3));' / 'const short fn = ((qid & 2) | short(simd_lid & 1)) * 4;' and the byte selector, verbatim: '// This lane's four k values of a 16-code word are byte (fn / 4).' over 'const ushort bsh = ushort(8 * (fn >> 2));' — the lane's NEED (which byte of which word) is a function of its fragment coordinate, and so is the SIBLING holding that word. THE LOAD SIDE: each lane loads ITS positional share — 'const ushort wq = ushort(fn >> 2);   // this lane's uint4 within the line' (qmv_nax2.zig:118) — one aligned uint4 per lane, four lanes covering the line; every global load is a full 16-byte vector from a contiguous 64-byte row segment, per weight row via 'auto block_line = [&](int i, int j) -> uint4 { const int gb = 2 * (int(ks) + 2 * i); return *((const device uint4*)(w + wrow[j] * K_w + gb * 8) + wq); };' (qmv_nax2.zig:127-130). THE EXCHANGE SIDE, verbatim (qmv_nax2.zig:122,167): 'qlane[st] = ushort((simd_lid & ~0x9u) | uint(st & 1) | (uint(st >> 1) << 3));' — the quad-internal permutation (lane bits 0 and 3 replaced by the word selector) — consumed as 'const uint word = simd_shuffle(ring[0][j][st & 3], qlane[st >> 2]);' — lane asks sibling qlane[word] for its component of the staged line: the 16 words of the block are held four-per-lane across the quad, and each 16-k step's word comes back with ONE shuffle. THE PREFETCH RING, verbatim (qmv_nax2.zig:131-136, then the loop tail at :210-216): 'uint4 ring[2][4];' primed with two blocks ('for (int j = 0; j < 4; ++j) ring[r][j] = block_line(r, j);'), consumed from ring[0], and rotated at the tail — 'for (int j = 0; j < 4; ++j) ring[0][j] = ring[1][j];' then the guarded refill 'if (i + 2 < my_blocks) { for (int j = 0; j < 4; ++j) ring[1][j] = block_line(i + 2, j); }' — 'one block stays in flight ahead of the one being consumed', depth TWO: the minimum that hides the line's latency under a 16-k step's tensor work. DECISION CONTENT: (a) the LOAD ASSIGNMENT FOLLOWS THE LINE, NOT THE NEED — the lane loads the word it is POSITIONED to load contiguously and exchanges for what its fragment needs; need-indexed loads are sub-word, unaligned, and re-touch the same line from every lane; (b) the exchange permutation is DERIVED from the fragment coordinate map (BaseNAXFrag::get_coord), never hand-tabulated — when the fragment layout changes, the permutation derives with it; (c) the exchange is INTRA-QUAD (4 lanes), so it rides registers and shuffles — no shared memory, no barriers, and the staged words never touch memory again ('the codes never land in memory'); (d) ring depth 2 with a guarded refill (the last block's fetch is skipped, not clamped); (e) the per-row word fetch is one expression over the block index — the four weight rows of the fragment ride ring[.][j], j = 0..3. REGIME: fragment-mapped kernels (tensor-unit MMA / cooperative-tensor operands) whose per-lane byte needs come from contiguous lines narrower than a threadgroup's collective consumption; simd-shuffle-bearing targets (Metal simdgroups, CUDA warps); decode/verify-width GEMVs where the weight row's line is read once and consumed across the quad. ANTI-REGIME: a lane's need already contiguous within its own word (load it directly — the exchange is pure overhead); lines wide enough that a whole warp/threadgroup co-loads them through shared memory (the smem-staging family is then the substrate — the exchange only wins while the group is a QUAD); backends without cross-lane shuffle (WGSL/Vulkan — the documented trade is a thread remap or smem, exactly the cost this rule avoids). KINSHIP (do not double-count): rope-pair-partner-via-cross-lane-shuffle (B110) owns the PAIRING shuffle — one xor distance derived from the transform's pair geometry, no arithmetic on the exchanged value; THIS owns WORD-DISTRIBUTION shuffle — a quad-permutation routing whole packed words to the fragment coordinate that needs them, the exchange payload and derivation both differ; warp-shuffle-intrinsics-for-sub-warp-reduction (B22) owns shuffle-as-reduction; THIS's shuffles MOVE data (no arithmetic on the exchanged value either, but the purpose is distribution, not convergence); register-rotation-prefetch-loop (B111) owns the register-rotation prefetch in a slot loop (prime current, guarded-prefetch next, rotate at the tail); THIS's ring[2] rotation is that shape instantiated on uint4 line blocks with the quad-exchange layered on top — cite as the substrate, the quad exchange is the new atom; cpasync-multistage-tile-prefetch-pipeline (B92) owns the SHARED-MEMORY multi-stage ring; THIS stays register-resident because the exchange group is 4 lanes, not a threadgroup; m-group-shared-weight-scan-register-relief (B110) shares one weight scan across a group from registers — adjacent on the weight-reuse axis, not the load-assignment axis. NotBenchable here (the route's own numbers — 1.0-1.6x stock at 6 rows, 1.3-2.8x at 8-16, near flat in rows — ride its header as provenance, never a bar; a host fixture cannot price intra-quad shuffle exchange). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (qmv_nax2.zig:55-64 the law doc, :87-93 the fragment coordinate + byte selector, :118 wq, :122 qlane, :127-137 block_line + ring + prime, :167 the shuffle consumption, :210-216 the rotation + guarded refill; every quote verbatim at the pin this session; route ported from Layr-Labs/mlxfast-bonsai2-27b-engine per its header; repo MIT). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: each lane loads the WORD ITS FRAGMENT NEEDS — the load\n// index is the need (fragment coordinate), so the four lanes of a\n// quad issue overlapping, unaligned loads into the same 64-byte line\n// every step, sibling lanes re-touch what a neighbour already fetched,\n// and no lane's full vector width is ever used.\nfn step_words_naive(need_word: usize, w_line: &[u32; 16]) -> u32 {\n    w_line[need_word] // need-indexed: sub-word, scattered, per step\n}".to_string(),
            opt_pattern: "// optimized: the quad CO-LOADS the line — each lane takes its\n// positional aligned uint4 share (16 bytes; four lanes cover the\n// 64-byte line), the words come back with simd_shuffle over a\n// quad-internal permutation derived from the fragment coordinate, and\n// a 2-deep register ring keeps one block in flight while the current\n// one is consumed.\nfn qlane(simd_lid: usize, word: usize) -> usize {\n    // (simd_lid & ~0x9) | (word & 1) | ((word >> 1) << 3): the sibling\n    // of my quad holding `word` — lane bits 0 and 3 replaced by the\n    // word selector, derived from the fragment coordinate map\n    (simd_lid & !0x9usize) | (word & 1) | ((word >> 1) << 3)\n}\n\n// ring[block][weight_row j][word 0..3] — one aligned uint4 per lane\nfn step_words_exchanged(\n    simd_lid: usize,\n    ring: &[[[u32; 4]; 4]; 2],\n    shuffle: impl Fn(u32, usize) -> u32,\n) -> [[u32; 4]; 4] {\n    let mut out = [[0u32; 4]; 4];\n    for j in 0..4 {\n        for st in 0..4 {\n            // my positional share is ring[0][j][st]; the word MY\n            // fragment needs sits in sibling qlane(st)'s share — ONE\n            // shuffle per word, no smem, no barrier\n            out[j][st] = shuffle(ring[0][j][st], qlane(simd_lid, st));\n        }\n    }\n    out\n}\n\nfn rotate_and_refill(\n    ring: &mut [[[u32; 4]; 4]; 2],\n    block_line: impl Fn(usize, usize) -> u32,\n    i: usize,\n    my_blocks: usize,\n) {\n    // ring[0] consumed: promote the in-flight block, guarded refill of\n    // the far slot (the last block's fetch is skipped, not clamped)\n    for j in 0..4 {\n        ring[0][j] = ring[1][j];\n    }\n    if i + 2 < my_blocks {\n        for j in 0..4 {\n            ring[1][j] = [\n                block_line(i + 2, j * 4),\n                block_line(i + 2, j * 4 + 1),\n                block_line(i + 2, j * 4 + 2),\n                block_line(i + 2, j * 4 + 3),\n            ];\n        }\n    }\n}".to_string(),
        },
        // ── L: the ambiguity-refusal inference law — a layout parameter
        // inferred from the artifact's byte geometry enumerates its
        // candidates and refuses when two fit; no-fit is its own error. ─
        KernelRule {
            rule_id: "tp-rank-inferred-from-scale-grid-ambiguity-refused".to_string(),
            gpu_concept: "MECHANISM (checkpoint layout parameter inferred from byte geometry, refused on ambiguity; category L — memory-layout inference at load): when a checkpoint stores a tensor whose meaning depends on an UNSTATED layout parameter — the tensor-parallel rank count that split one fused [q|k|v] projection into tp slabs, each with its own block-scale grid — infer the parameter by ENUMERATING the candidate values against an invariant the artifact's own byte geometry carries, and REFUSE on ambiguity (two candidates fit) as loudly as on no fit: a necessary-condition key that two candidates satisfy is too weak for this artifact, and a silent first-match pick mis-slices every tensor loaded after it. THE LAW, verbatim (sushi_pack.zig:265-266): '/// The tensor-parallel rank count whose slabs `[q|k|v]` tile into exactly `scale_rows` grid rows (each slab tiles its own rows, so a slab's last tile may be partial).' THE ENUMERATION + INVARIANT, verbatim (sushi_pack.zig:269-272): 'for ([_]u64{ 8, 4 }) |tp| {' then 'if (q % tp != 0 or k % tp != 0 or v % tp != 0) continue;' then 'const per = (q + k + v) / tp;' then 'if (scale_rows != tp * ((per + FP8_BLOCK - 1) / FP8_BLOCK)) continue;' — the candidates are EXPLICIT (8, 4, descending), and the test is a GEOMETRY EQUALITY the artifact already carries: the FP8 scale grid's row count equals tp times the per-slab tile count (each slab tiles its OWN rows; a slab's last tile may be partial — hence the ceiling division), no thresholds, no heuristics. THE TWO REFUSAL CLASSES, verbatim (sushi_pack.zig:273,276): 'if (found != null) return error.AmbiguousQkvTensorParallelism;' and 'return found orelse error.InvalidQkvGeometry;' — AMBIGUOUS (two candidates fit the grid) is a DISTINCT error from INVALID (none fits): the first says the key is too weak for this artifact, the second says the geometry is not what any candidate describes; both are load-time failures that name their class, never silent picks. DECISION CONTENT: (a) infer only from DERIVED INVARIANTS of the byte layout (scale_rows == tp * ceil(per/128)), not from naming conventions or file metadata guesses; (b) enumerate candidates explicitly, descending, so the refusal is deterministic; (c) AMBIGUITY IS AN ERROR — a first-match-wins loop turns an underdetermined artifact into a confidently wrong load; record the ambiguity class separately from no-fit because their REMEDIES differ (re-derive the key vs re-examine the tensor); (d) the inference is load-time ONCE — a wrong tp poisons every downstream split, which is why the refusal is loud. REGIME: checkpoint/artifact loaders inferring unstated layout parameters from byte geometry (TP rank, head splits, padding granularity, slab ordering); one-shot load paths where a silent mis-inference cascades into every tensor after it. ANTI-REGIME: metadata present in the artifact (read it — inference is the fallback, never the preference); keys that are SUFFICIENT conditions (a unique fit is still a fit — the refusal is for the ambiguous class only); per-request inference (load-time once; there is nothing to gain re-running it). KINSHIP (do not double-count): shape-class-keyed-capability (B103) owns per-shape-class verdict keying and the 'fails loudly at install' doctrine — THIS is the loader-side instance of that doctrine: a geometric inference that refuses loudly rather than guessing; enumerable-domain-bit-identity-admission-gate (B195) enumerates a whole domain to ADMIT a rewrite — THIS enumerates two candidates and refuses when the enumeration does not DECIDE (the failure mode is ambiguity, not sampling); the B226 probe-shape-class rider (on fa-fast-path-validated-exact-shape-admission, B208) owns probe-domain validity (a probe's verdict holds only inside its sampled class); THIS owns inference-key STRENGTH (necessary vs sufficient condition) — a key that two artifacts satisfy says nothing about which one you are holding. NotBenchable here (a 13-line loader inference; no perf surface — the law is the refusal classes). Source: ddalcu/mlx-serve @ 1015f7854fd8ee5c22e34993aaddee2443b9cfbf (sushi_pack.zig:265-266 the doc, :267-277 solveQkvTp — the candidate loop, the divisibility and geometry tests, both error classes; every quote verbatim at the pin this session; repo MIT). Batch 242 / Plan 244 / Research 274.".to_string(),
            ref_shape: "// naive: first match wins — the loop returns the first tp whose\n// divisibility and geometry hold, so an artifact whose scale grid\n// fits BOTH 8 and 4 silently loads as whichever the loop met first,\n// and no-fit falls through to a guessed single rank: every slab after\n// it is mis-sliced with no error anywhere.\nfn solve_tp_first_match(q: u64, k: u64, v: u64, scale_rows: u64) -> u32 {\n    for tp in [8u64, 4] {\n        if q % tp != 0 || k % tp != 0 || v % tp != 0 {\n            continue;\n        }\n        let per = (q + k + v) / tp;\n        if scale_rows == tp * per.div_ceil(128) {\n            return tp as u32; // AMBIGUOUS artifacts land here silently\n        }\n    }\n    1 // and no-fit guesses single-rank\n}".to_string(),
            opt_pattern: "// optimized: enumerate the candidates against the artifact's own\n// geometry invariant; AMBIGUITY (two fits) is an error, not a\n// first-match win, and no-fit is its own error naming the class —\n// the remedies differ (re-derive the key vs re-examine the tensor).\n#[derive(Debug)]\nenum TpError {\n    Ambiguous, // two candidates fit the scale grid\n    Invalid,   // none fits\n}\n\nfn solve_tp(q: u64, k: u64, v: u64, scale_rows: u64) -> Result<u32, TpError> {\n    let mut found: Option<u32> = None;\n    for tp in [8u64, 4] {\n        if q % tp != 0 || k % tp != 0 || v % tp != 0 {\n            continue;\n        }\n        let per = (q + k + v) / tp;\n        // each slab tiles its OWN rows; a slab's last tile may be\n        // partial — hence the ceiling division\n        if scale_rows != tp * per.div_ceil(128) {\n            continue;\n        }\n        if found.is_some() {\n            return Err(TpError::Ambiguous);\n        }\n        found = Some(tp as u32);\n    }\n    found.ok_or(TpError::Invalid)\n}".to_string(),
        },
    ]
}
